add_filter( 'wp_handle_upload', 'perfectpixel_limit_uploaded_image_size' );

function perfectpixel_limit_uploaded_image_size( $upload ) {
	if ( empty( $upload['file'] ) || empty( $upload['type'] ) || ! in_array( $upload['type'], array( 'image/jpeg', 'image/png', 'image/webp' ), true ) ) {
		return $upload;
	}
	$max_w = max( 100, (int) '{{max_upload_width}}' );
	$max_h = max( 100, (int) '{{max_upload_height}}' );
	$size  = @getimagesize( $upload['file'] );
	if ( ! $size || ( $size[0] <= $max_w && $size[1] <= $max_h ) ) {
		return $upload;
	}
	$editor = wp_get_image_editor( $upload['file'] );
	if ( is_wp_error( $editor ) ) {
		return $upload;
	}
	$editor->maybe_exif_rotate();
	if ( ! is_wp_error( $editor->resize( $max_w, $max_h, false ) ) ) {
		$editor->save( $upload['file'] );
	}
	return $upload;
}
